using System;
using System.IO;
using System.Collections.Generic;
using WoWProbe;
class QuickServiceRouteTests
{
    static int passed,failed;static void Check(bool value){if(!value)throw new Exception("Recorded service behavior differs.");}
    static void Test(string name,Action run){try{run();passed++;Console.WriteLine("PASS "+name);}catch(Exception e){failed++;Console.WriteLine("FAIL "+name+": "+e.Message);}}
    static void Reject(Action run){bool rejected=false;try{run();}catch(InvalidOperationException){rejected=true;}catch(FormatException){rejected=true;}Check(rejected);}
    static QuickRoutePlan Plan(){var p=new QuickRoutePlan{Calibration=new NavigationCalibration{MapId=42,MapMode=1,Zone="TEST",Confirmed=true,AxisScale=1.5},Route=new RouteDocument{RouteId="farm",Name="ABCA",MapId=42,MapMode=1,Zone="TEST",Loop=true}};foreach(var xy in new[]{new[]{.5,.5},new[]{.6,.5},new[]{.6,.6},new[]{.5,.5}})p.Route.Points.Add(new Waypoint{X=xy[0],Y=xy[1],Tolerance=.001});return p;}
    static FarmObservation O(double x=.5,double y=.5){return new FarmObservation{Fresh=true,KnownCore=true,MapId=42,MapMode=1,Zone="TEST",X=x,Y=y,Sequence=1,Health=100,ChatOpenKnown=true,CastingKnown=true};}
    static QuickVendorSettings Service(){var s=new QuickVendorSettings{Enabled=true,RouteComplete=true,X=.52,Y=.52};foreach(var xy in new[]{new[]{.5,.5},new[]{.5,.52},new[]{.52,.52}})s.Points.Add(new Waypoint{X=xy[0],Y=xy[1],Tolerance=.0004});return s;}
    static int Main()
    {
        Test("enabled empty merchant configuration permits recording but never live service",()=>{var p=Plan();p.Vendor.Enabled=p.Repair.Enabled=true;p.Validate(false);Reject(()=>p.Validate(true));var o=O(.8,.8);var r=new QuickServiceRecording(p,o,0);o.X+=.001;o.Sequence++;Check(r.Finish(o,200,p.Vendor).RouteComplete);});
        Test("arbitrary service origin records and automatic full bags visit origin before remaining path",()=>{var p=Plan();var s=Service();foreach(var w in s.Points){w.X+=.3;w.Y+=.3;}s.X+=.3;s.Y+=.3;p.Vendor=s;var o=O(s.Points[1].X,s.Points[1].Y);Check(new QuickServiceRecording(p,o,0).Count==1);var automatic=QuickServicePaths.Outbound(p,s,o,false);Check(automatic.Points.Count==4&&automatic.Points[1].X==s.Points[0].X&&automatic.Points[1].Y==s.Points[0].Y);var manual=QuickServicePaths.Outbound(p,s,o);Check(manual.Points.Count==2);Check(QuickServicePaths.StartReturn(p,O(s.X,s.Y))!=null);var back=QuickServicePaths.TripReturn(p,s,automatic,O(s.X,s.Y));Check(back.Points[back.Points.Count-1].X==o.X);});
        Test("ghost recording permits graveyard start but allows resurrection and still requires farm destination",()=>{var p=Plan();var o=O(.45,.5);o.PlayerDead=o.PlayerGhost=true;var r=new QuickServiceRecording(p,o,0,true);o.X=.451;o.Sequence++;Check(r.Observe(o,200));Reject(()=>r.Finish(o,300,new QuickVendorSettings()));o.PlayerGhost=false;Reject(()=>r.Observe(o,400));o=O(.5,.5);o.PlayerDead=o.PlayerGhost=true;r=new QuickServiceRecording(p,o,0,true);o.X+=.001;o.Sequence++;o.PlayerDead=o.PlayerGhost=false;Check(r.Finish(o,200,new QuickVendorSettings()).RouteComplete);Check(new QuickServiceRecording(p,o,0,true).Count==1);});
        Test("merchant return includes missing recorded prefix after a mid route or NPC start",()=>{var p=Plan();var s=Service();foreach(var o in new[]{O(.5,.52),O(.52,.52)}){var forward=QuickServicePaths.Outbound(p,s,o);var back=QuickServicePaths.TripReturn(p,s,forward,O(.52,.52));Check(back.Points.Count==3&&back.Points[1].X==.5&&back.Points[1].Y==.52&&back.Points[2].Y==.5);}});
        Test("service startup return uses bounded forward and stationary turning at recorded corners",()=>{var p=Plan();p.Vendor=Service();var o=O(.52,.52);o.Facing=Math.PI/2;var f=new QuickRouteFollower(p,o);var forward=f.Step(o,0);Check(forward.Action==QuickAction.Patrol&&forward.PauseForward&&forward.Hold<=3000);o.X=.5;o.Sequence++;f.Step(o,100);o.Sequence++;var turn=f.Step(o,200);Check(turn.Action==QuickAction.Turn&&turn.PauseForward);});
        Test("off route service restart joins nearest recorded point then follows remaining corners",()=>{var p=Plan();p.Vendor=Service();var path=QuickServicePaths.Outbound(p,p.Vendor,O(.498,.52));Check(path.Points.Count==3&&path.Points[1].X==.5&&path.Points[1].Y==.52&&path.Points[2].X==.52);});
        Test("mid service route resumes toward NPC or reverses to farm without distant patrol shortcut",()=>{var p=Plan();p.Vendor=Service();var o=O(.5,.52);var forward=QuickServicePaths.Outbound(p,p.Vendor,o);Check(forward.Points.Count==2&&forward.Points[1].X==.52);var back=QuickServicePaths.StartReturn(p,o);Check(back.Points.Count==2&&back.Points[1].X==.5&&back.Points[1].Y==.5);});
        Test("dense straight samples merge but a recorded obstacle corner remains",()=>{var p=Plan();var path=QuickServicePaths.Empty(p);for(int i=0;i<8;i++)path.Points.Add(new Waypoint{X=.5,Y=.5+i*.0004,Tolerance=.0004});path.Points.Add(new Waypoint{X=.501,Y=.5028,Tolerance=.0004});var fast=QuickServicePaths.StraightSegments(p,path);Check(fast.Points.Count==3&&fast.Points[1].X==.5&&fast.Points[1].Y==.5028);Check(QuickServicePaths.Navigate(p,path,O()).ForwardPulseLimit==3000);});
        Test("starting at merchant reverses every recorded corner before patrol even after combat or rest",()=>{var p=Plan();p.Vendor=Service();var o=O(.52,.52);o.Facing=0;var f=new QuickRouteFollower(p,o);Check(f.ReturningFromService&&!f.SearchingNearby&&!f.MayAcquire(o));f.BeginNearbySearch(o,0);f.TickNearbySearch(o,4000,true);Check(!f.SearchingNearby);o.InCombat=true;f.Interrupt(o);f.Resume();o.InCombat=false;o.X=.5;o.Sequence++;Check(f.Step(o,4100).Action!=QuickAction.Stop&&f.ReturningFromService);o.Y=.5;o.Sequence++;Check(f.Step(o,4200).Action!=QuickAction.Stop&&!f.ReturningFromService);Check(QuickServicePaths.StartReturn(p,O(.59,.5))==null);p.Repair=p.Vendor;p.Vendor=new QuickVendorSettings();Check(QuickServicePaths.StartReturn(p,O(.52,.52))!=null);});
        Test("record walking corners endpoint and independent cloned settings",()=>{var p=Plan();var o=O();var r=new QuickServiceRecording(p,o,0);Check(!r.Observe(o,100));o.Y+=.001;o.Sequence++;Check(r.Observe(o,200));o.X+=.001;o.Sequence++;Check(r.Observe(o,400));var s=r.Finish(o,500,new QuickVendorSettings());Check(s.Enabled&&s.RouteComplete&&s.Points.Count==3&&s.X==o.X&&s.Y==o.Y);var c=s.Clone();c.Points[1].Y=.9;Check(s.Points[1].Y!=.9);});
        Test("stationary finish cross map and a missing section never manufacture a route",()=>{var p=Plan();var o=O();var r=new QuickServiceRecording(p,o,0);Reject(()=>r.Finish(o,100,new QuickVendorSettings()));o.MapId++;Reject(()=>r.Observe(o,200));o.MapId--;o.X+=.03;o.Sequence++;Reject(()=>r.Observe(o,400));r=new QuickServiceRecording(p,O(),0);o=O(.505,.5);Reject(()=>r.Observe(o,4000));Check(new QuickServiceRecording(p,O(.8,.8),0).Count==1);});
        Test("outbound follows patrol vertices and recorded dogleg instead of a diagonal shortcut",()=>{var p=Plan();var s=Service();var path=QuickServicePaths.Outbound(p,s,O(.59,.5));Check(path.Points.Exists(w=>w.X==.6&&w.Y==.5));Check(path.Points.Exists(w=>w.X==.6&&w.Y==.6));int corner=path.Points.FindIndex(w=>w.X==.5&&w.Y==.52);Check(corner>=0&&corner<path.Points.Count-1);var back=QuickServicePaths.Return(p,path,O(.52,.52));Check(back.Points[0].X==.52&&back.Points[1].X==.5&&back.Points[1].Y==.52);Check(back.Points[back.Points.Count-1].X==.59);});
        Test("patrol projection joins ahead on the same segment without circling the whole farm",()=>{var p=Plan();var s=Service();s.Points[0].X=.55;var path=QuickServicePaths.Outbound(p,s,O(.52,.5));Check(!path.Points.Exists(w=>w.X==.6));Check(path.Points[1].X==.55);});
        Test("live trips require completed recorded routes while old coordinate JSON remains readable",()=>{var p=Plan();p.Vendor=new QuickVendorSettings{Enabled=true,X=.5,Y=.5};p.Validate(false);Reject(()=>p.Validate(true));string file=Path.Combine(Path.GetTempPath(),"service-"+Guid.NewGuid()+".json");try{var json=new System.Web.Script.Serialization.JavaScriptSerializer();var root=json.Deserialize<Dictionary<string,object>>(json.Serialize(p));var service=(Dictionary<string,object>)root["Vendor"];service.Remove("Points");service.Remove("RouteComplete");File.WriteAllText(file,json.Serialize(root));var old=QuickRoutePlan.Load(file);Check(old.Vendor.Enabled&&old.Vendor.Points.Count==0);Reject(()=>old.Vendor.RequireRoute());p.Vendor=Service();QuickRoutePlan.Save(file,p);var loaded=QuickRoutePlan.Load(file);Check(loaded.Vendor.Points.Count==3&&loaded.Vendor.RouteComplete);loaded.Vendor.Points[0].X=.8;Check(p.Vendor.Points[0].X==.5);}finally{if(File.Exists(file))File.Delete(file);}});
        Test("interrupted navigation retains remaining corners and return uses the entire outbound path",()=>{var p=Plan();var path=QuickServicePaths.Outbound(p,Service(),O());var nav=QuickServicePaths.Navigate(p,path,O(.5,.501),1);Check(nav.WorkingRoute.Points.Exists(w=>w.X==.5&&w.Y==.52));Check(nav.WorkingRoute.Points[nav.WorkingRoute.Points.Count-1].X==.52);});
        Console.WriteLine("Recorded service routes: "+passed+" passed, "+failed+" failed. No game input.");return failed==0?0:1;
    }
}
